mapper.select:
SELECT
FROM user_coupon uc JOIN coupon c ON c.id = uc.coupon_id WHERE uc.deleted = 0 AND uc.user_id = #{userId}
AND uc.status = #{status}
ORDER BY uc.status ASC, uc.expire_time ASC, uc.id DESC

SELECT uc.id, uc.coupon_id AS couponId, uc.user_id AS userId, uc.status, uc.order_no AS orderNo, uc.used_time AS usedTime, uc.expire_time AS expireTime, uc.create_time AS createTime, c.name AS couponName, c.type, c.scope, c.threshold, c.amount, c.discount, u.username AS username, u.nickname AS nickname FROM user_coupon uc JOIN coupon c ON c.id = uc.coupon_id LEFT JOIN `user` u ON u.id = uc.user_id WHERE uc.deleted = 0
AND uc.coupon_id = #{q.couponId}
AND uc.user_id = #{q.userId}
AND uc.status = #{q.status}
AND ( u.username LIKE CONCAT('%', #{q.keyword}, '%') OR u.nickname LIKE CONCAT('%', #{q.keyword}, '%') OR c.name LIKE CONCAT('%', #{q.keyword}, '%') OR uc.order_no LIKE CONCAT('%', #{q.keyword}, '%') )
AND uc.create_time >= #{q.startTime}
AND uc.create_time <= #{q.endTime}
ORDER BY uc.id DESC
